<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use DI\ContainerBuilder;
use Slim\Psr7\Factory\ServerRequestFactory;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\OidcFlowContext;

/**
 * Unit tests for {@see OidcFlowContext}.
 */
final class OidcFlowContextUnitTest extends TestCase
{
    private array $serverBackup = [];

    protected function setUp(): void
    {
        $this->serverBackup = $_SERVER;
        $_SERVER['HTTPS'] = 'on';
        $_SERVER['HTTP_HOST'] = 'example.com';
        $_SERVER['SCRIPT_NAME'] = '/index.php';
    }

    protected function tearDown(): void
    {
        $_SERVER = $this->serverBackup;
    }

    /**
     * Verifies fromRequest normalizes query, cookies, and locale.
     */
    public function testFromRequestBuildsNormalizedContext(): void
    {
        /* Arrange: build request with query, cookies, and locale. */
        $request = (new ServerRequestFactory())
            ->createServerRequest('GET', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid profile',
                'nonce' => 'nonce-abc',
                'audience' => 'api, other, ,api',
            ])
            ->withCookieParams([
                'AUTH_SESSION_ID_TENANT1' => 'sess-123',
                'PRE_SESSION_ID' => 'pre-456',
            ])
            ->withHeader('accept-language', 'es-ES,es;q=0.9');

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $context = new Context($builder, $config);

        /* Act: build context from request. */
        $flow = OidcFlowContext::fromRequest($request, 'tenant1', $context);

        /* Assert: context values are normalized and derived. */
        $this->assertSame('tenant1', $flow->tenant);
        $this->assertSame('client-123', $flow->clientId);
        $this->assertSame('https://client.example/callback', $flow->redirect);
        $this->assertSame('openid profile', $flow->scope);
        $this->assertSame('code', $flow->responseType);
        $this->assertSame('state-xyz', $flow->state);
        $this->assertSame('nonce-abc', $flow->nonce);
        $this->assertSame(['api', 'other'], $flow->audiences);
        $this->assertSame('', $flow->prompt);
        $this->assertSame('es-ES,es;q=0.9', $flow->locale);
        $this->assertSame('https://example.com', $flow->baseUrl);
        $this->assertSame('https://example.com/openid/tenant1', $flow->issuer);
        $this->assertSame('sess-123', $flow->sessionId);
        $this->assertSame('pre-456', $flow->preSessionId);
    }
}
